Object obj = ints;
// Bytecode equivalent:
List rawInts = (List) obj;
System.out.println(rawInts.get(0).getClass().getName());

public static <T extends Comparable<T>> int compare(T a, T b) {
    return a.compareTo(b);
}
System.out.println(compare("apple", "banana"));
System.out.println(compare(10, 5));

public <T> void addToList(List<T> list, T item) {
    list.add(item);
}
List rawList = new ArrayList<String>();
addToList(rawList, 42);

public static <T> T firstOrDefault(List<T> list, T defaultVal) {
    return list.isEmpty() ? defaultVal : list.get(0);
}
firstOrDefault(List.of("a","b"), "");
firstOrDefault(List.of(1, 2), 0);
firstOrDefault(new ArrayList<>(), null);
